import{_ as t,o as a,c as r,a5 as n}from"./chunks/framework.bIR-4glx.js";const p=JSON.parse('{"title":"Reading Evidence Card: From Finished Summary to Real Delivery","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/worksheets/reading-evidence.en.md","filePath":"public/downloads/worksheets/reading-evidence.en.md","lastUpdated":1795488252000}'),d={name:"public/downloads/worksheets/reading-evidence.en.md"};function i(o,e,s,l,c,h){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="reading-evidence-card-from-finished-summary-to-real-delivery" tabindex="-1">Reading Evidence Card: From Finished Summary to Real Delivery <a class="header-anchor" href="#reading-evidence-card-from-finished-summary-to-real-delivery" aria-label="Permalink to &quot;Reading Evidence Card: From Finished Summary to Real Delivery&quot;">​</a></h1><p>Finishing a text is an action, not proof of comprehension. Copy this card into a private note for one article, chapter, documentation section, or source set at a time. Do not record passwords, client data, unauthorised third-party information, or unnecessary personal details.</p><h2 id="_1-define-the-task-reader-and-boundary" tabindex="-1">1. Define the Task, Reader, and Boundary <a class="header-anchor" href="#_1-define-the-task-reader-and-boundary" aria-label="Permalink to &quot;1. Define the Task, Reader, and Boundary&quot;">​</a></h2><h3 id="reading-evidence-yyyy-mm-dd" tabindex="-1">Reading Evidence - YYYY-MM-DD <a class="header-anchor" href="#reading-evidence-yyyy-mm-dd" aria-label="Permalink to &quot;Reading Evidence - YYYY-MM-DD&quot;">​</a></h3><p>Real situation:<br> Task: locate information / follow an argument / read documentation / build stamina / synthesise sources / support a decision<br> Who must know, decide, execute, or continue something after the reading?<br> Completion standard:<br> Time limit:<br> Dictionary / translation / search / notes / AI allowed:<br> Copyright, privacy, and retention boundary:</p><p>Write completion as a result, such as &quot;can run the minimum example under the current version&quot;, not only &quot;finished&quot;.</p><h2 id="_2-record-source-and-version" tabindex="-1">2. Record Source and Version <a class="header-anchor" href="#_2-record-source-and-version" aria-label="Permalink to &quot;2. Record Source and Version&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Main source</th><th>Parallel source</th><th>Comparable?</th></tr></thead><tbody><tr><td>Author/maintainer, title, link</td><td></td><td></td><td></td></tr><tr><td>Edition, publication date, or version</td><td></td><td></td><td></td></tr><tr><td>Access date and length</td><td></td><td></td><td></td></tr><tr><td>Author/institution position or interest</td><td></td><td></td><td></td></tr><tr><td>Quotation, image, code, and copyright boundary</td><td></td><td></td><td></td></tr><tr><td>Topic, genre, and difficulty</td><td></td><td></td><td></td></tr></tbody></table><p>Web pages change, become paid, or disappear. Keep necessary citation details; do not copy an entire article without permission.</p><h2 id="_3-preserve-an-unpolished-first-pass" tabindex="-1">3. Preserve an Unpolished First Pass <a class="header-anchor" href="#_3-preserve-an-unpolished-first-pass" aria-label="Permalink to &quot;3. Preserve an Unpolished First Pass&quot;">​</a></h2><p>First-pass conditions:<br> First-pass time:<br> Did I look up every word?<br> One-sentence gist:<br> How the text moves:<br> Three certain details:<br> What the author/maintainer wants me to believe or do:<br> One unresolved point:<br> Action I would take from this understanding:</p><p>Finish the first pass before checking words or explanations. Do not replace it with a polished translation.</p><h2 id="_4-build-a-six-layer-barrier-map" tabindex="-1">4. Build a Six-Layer Barrier Map <a class="header-anchor" href="#_4-build-a-six-layer-barrier-map" aria-label="Permalink to &quot;4. Build a Six-Layer Barrier Map&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Paragraph/page</th><th>Where I got stuck</th><th>Barrier layer</th><th>Task impact</th><th>This cycle&#39;s action</th></tr></thead><tbody><tr><td></td><td></td><td>vocabulary/grammar / structure/reference / background/schema / argument/evidence / layout/technical / attention/capacity</td><td>meaning-changing / task-blocking / recurring / effortful / low-impact</td><td></td></tr></tbody></table><p>One to three barriers that most affect the task:<br> Low-impact words or sentences I will skip for now:<br> Possible device, version, fatigue, or environment effects:</p><p>If almost every sentence blocks the gist, choose easier parallel material or learn domain chunks first. Lowering the entry point does not lower the destination.</p><h2 id="_5-map-claims-evidence-and-limits" tabindex="-1">5. Map Claims, Evidence, and Limits <a class="header-anchor" href="#_5-map-claims-evidence-and-limits" aria-label="Permalink to &quot;5. Map Claims, Evidence, and Limits&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Paragraph/page</th><th>Function</th><th>Author claim</th><th>Source evidence/example</th><th>Limit, counterexample, or unknown</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><p>Facts stated directly:<br> Inference supported by the source:<br> My own judgment or association:<br> Evidence still missing:<br> What new evidence would change my judgment:</p><p>Separate what the author says from whether you agree. For technical, health, legal, or financial claims, return to reliable primary sources or qualified professional advice.</p><h2 id="_6-technical-documentation-fact-card" tabindex="-1">6. Technical Documentation Fact Card <a class="header-anchor" href="#_6-technical-documentation-fact-card" aria-label="Permalink to &quot;6. Technical Documentation Fact Card&quot;">​</a></h2><p>For an API, SDK, migration guide, command-line help, error reference, or README, add:</p><p>Goal and applicable version:<br> Prerequisites, permissions, and environment:<br> Minimum input:<br> Expected output:<br> Actual output:<br> Defaults, ranges, order, or side effects:<br> Failure condition/error:<br> Limit explicitly stated in the source:<br> Part I am still inferring:<br> Smallest next test:</p><p>Reading documentation without running, reasoning through, reproducing, or confirming one minimum fact shows that you saw the page. It does not show mastery.</p><h2 id="_7-record-unknown-words-word-families-and-translation" tabindex="-1">7. Record Unknown Words, Word Families, and Translation <a class="header-anchor" href="#_7-record-unknown-words-word-families-and-translation" aria-label="Permalink to &quot;7. Record Unknown Words, Word Families, and Translation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Word/expression</th><th>Role in the task</th><th>Definition/family/collocation checked</th><th>Source location</th><th>Explainable after tools close?</th></tr></thead><tbody><tr><td></td><td>core / recurring / technical / low-impact</td><td></td><td></td><td></td></tr></tbody></table><p>Background the translation helped me supply:<br> English structure, stance, or qualifier the translation may hide:<br> Word I decided not to check yet:</p><p>Unknown-word count diagnoses source fit; it does not directly set a level. Word families help guessing and coverage, but a derived form is not automatically usable.</p><h2 id="_8-compare-sources-and-deliver-an-output" tabindex="-1">8. Compare Sources and Deliver an Output <a class="header-anchor" href="#_8-compare-sources-and-deliver-an-output" aria-label="Permalink to &quot;8. Compare Sources and Deliver an Output&quot;">​</a></h2><p>Shared question:<br> Definition, date, and evidence in source A:<br> Definition, date, and evidence in source B:<br> Omitted evidence or institutional interest:<br> Which differences are factual, and which are values?</p><table tabindex="0"><thead><tr><th>Output</th><th>Audience</th><th>What I delivered</th><th>Audience response</th><th>Traceable basis?</th></tr></thead><tbody><tr><td>Confirmation / minimum test / explanation / decision memo / handover</td><td></td><td></td><td></td><td></td></tr></tbody></table><p>After reading, let a reader, code, decision, or next task test the understanding.</p><h2 id="_9-record-tools-and-feedback" tabindex="-1">9. Record Tools and Feedback <a class="header-anchor" href="#_9-record-tools-and-feedback" aria-label="Permalink to &quot;9. Record Tools and Feedback&quot;">​</a></h2><p>Tool / reviewer / version and date:<br> Did it see the source, my first pass, or my summary?<br> Source locations it says I missed:<br> Did it confuse fact, inference, and style?<br> Teacher/peer/primary-source check:<br> What I accepted/rejected, and why:</p><p>AI may extract candidate terms, ask structural questions, and create parallel tasks, but it may invent summaries, citations, background, and author intention. Preserve the first pass before asking it to locate evidence.</p><h2 id="_10-test-delayed-retention-and-transfer" tabindex="-1">10. Test Delayed Retention and Transfer <a class="header-anchor" href="#_10-test-delayed-retention-and-transfer" aria-label="Permalink to &quot;10. Test Delayed Retention and Transfer&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Date</th><th>What is removed</th><th>Changed condition</th><th>Output</th><th>Result</th></tr></thead><tbody><tr><td>Day 1</td><td>No full translation or AI summary</td><td>Main source</td><td>First pass and five-sentence reconstruction</td><td></td></tr><tr><td>Days 3-7</td><td>Old notes and dictionary removed</td><td>Parallel source</td><td>Gist, evidence, and inference</td><td></td></tr><tr><td>Day 14</td><td>Recent feedback removed</td><td>New topic or genre</td><td>Explanation, test, or decision memo</td><td></td></tr><tr><td>Day 30</td><td>All prompts closed</td><td>Real document, report, or handover</td><td>Complete delivery</td><td></td></tr></tbody></table><p>Method still available after seven days:<br> Barrier that returned after the source changed:<br> Did word-by-word translation or summary dependence decrease?<br> Which post-reading action remains unstable?<br> One variable for the next cycle:</p><h2 id="_11-score-and-decide" tabindex="-1">11. Score and Decide <a class="header-anchor" href="#_11-score-and-decide" aria-label="Permalink to &quot;11. Score and Decide&quot;">​</a></h2><p>Score 0-2: <code>0=not completed</code>, <code>1=prompt-dependent or unstable</code>, <code>2=completed under the current condition</code>.</p><table tabindex="0"><thead><tr><th>Item</th><th style="text-align:right;">Day 1</th><th style="text-align:right;">Day 7</th><th style="text-align:right;">Day 14</th><th>Evidence reason</th></tr></thead><tbody><tr><td>Preserve the first-pass main line</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Separate claim, evidence, and inference</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Locate the barrier layer and choose an action</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Verify a technical fact or source location</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Reconstruct after tools close</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Deliver after source, topic, or genre changes</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr></tbody></table><p>Current evidence supports: continue main source / downgrade to extensive reading / replace source / move to another problem<br> Most important evidence:<br> Conclusion I still cannot draw:<br> Smallest next task:<br> Next review date:</p><p>Related chapters: <a href="https://byoungd.github.io/up/en/threads/part-1/4-reading" target="_blank" rel="noreferrer">Reading: From Word-by-word Translation to Claims and Evidence</a> | <a href="https://byoungd.github.io/up/en/threads/part-1/2-vocabulary" target="_blank" rel="noreferrer">Vocabulary</a> | <a href="https://byoungd.github.io/up/en/threads/part-1/grammar" target="_blank" rel="noreferrer">Grammar</a> | <a href="https://byoungd.github.io/up/en/threads/part-1/3-listening" target="_blank" rel="noreferrer">Listening</a> | <a href="https://byoungd.github.io/up/en/threads/part-1/7-ai" target="_blank" rel="noreferrer">Learning English with AI</a> | <a href="https://byoungd.github.io/up/en/templates/evidence-chain" target="_blank" rel="noreferrer">Evidence Chain Template</a></p><hr><p>Source: <a href="https://byoungd.github.io/up/en/templates/reading-evidence" target="_blank" rel="noreferrer">Still Here</a> · Manuscript updated: 2026-09-02. Content: <a href="https://creativecommons.org/licenses/by-nc/4.0/" target="_blank" rel="noreferrer">CC BY-NC 4.0</a>.</p>',45)])])}const m=t(d,[["render",i]]);export{p as __pageData,m as default};
